(function () {
  var CFG = { version: 1, optimizeId: '117911758' };
  window.dataLayer = window.dataLayer || [];
  function gtag() { window.dataLayer.push(arguments); }
  window.gtag = window.gtag || gtag;
  var saved = null;
  try {
    var m = document.cookie.match(/(?:^|;\s*)nc_consent=([^;]*)/);
    if (m) saved = JSON.parse(decodeURIComponent(m[1]));
    if (!saved || saved.v !== CFG.version) saved = null;
  } catch (e) { saved = null; }
  var analytics = !!(saved && saved.analytics);
  var personalization = !!(saved && saved.personalization);

  /* Webflow queues gtag('js') and gtag('config') in its own head snippet, which
     it injects ABOVE this custom-code slot. Appending the consent default would
     put it after config, and GA would fire a pageview (setting _ga) before the
     default applied. gtag.js is loaded async and has not executed yet, so the
     dataLayer is still a plain array here: insert the consent commands in FRONT
     of the first js/config command instead of appending them. */
  function A() { return arguments; }
  var cmds = [
    A('consent', 'default', {
      ad_storage: 'denied',
      ad_user_data: 'denied',
      ad_personalization: 'denied',
      analytics_storage: analytics ? 'granted' : 'denied',
      personalization_storage: personalization ? 'granted' : 'denied',
      functionality_storage: 'granted',
      security_storage: 'granted',
      wait_for_update: 500
    }),
    A('set', 'ads_data_redaction', true),
    A('set', 'url_passthrough', true)
  ];

  var dl = window.dataLayer;
  if (dl.push === Array.prototype.push) {
    var at = dl.length;
    for (var i = 0; i < dl.length; i++) {
      var c = dl[i];
      if (c && (c[0] === 'js' || c[0] === 'config')) { at = i; break; }
    }
    Array.prototype.splice.apply(dl, [at, 0].concat(cmds));
  } else {
    /* gtag.js already took over dataLayer.push — fall back to normal order */
    for (var k = 0; k < cmds.length; k++) dl.push(cmds[k]);
  }

  window.clarity = window.clarity || function () {
    (window.clarity.q = window.clarity.q || []).push(arguments);
  };
  window.clarity('consent', analytics);

  try {
    var out = 'intellimize_opt_out_' + CFG.optimizeId;
    var choice = 'intellimize_user_tracking_choice_' + CFG.optimizeId;
    if (personalization) {
      localStorage.removeItem(out);
      localStorage.setItem(choice, 'allow');
    } else {
      localStorage.setItem(out, 'true');
      localStorage.setItem(choice, 'deny');
      localStorage.setItem('intellimize_data_tracking_type', 'optOut');
    }
  } catch (e) {}
})();

window.addEventListener("load", function () {
  if (
    typeof SplitText === "undefined" ||
    typeof ScrambleTextPlugin === "undefined"
  ) {
    console.warn("GSAP plugins missing. Animation skipped.");
    return;
  }
  gsap.registerPlugin(ScrollTrigger, SplitText, ScrambleTextPlugin);
  const revealElements = document.querySelectorAll("[data-reveal]");
  revealElements.forEach((element) => {
    const mode = element.getAttribute("data-reveal");
    const d_duration = parseFloat(element.getAttribute("data-duration")) || 1;
    const d_delay = parseFloat(element.getAttribute("data-delay")) || 0.25;
    const d_stagger = parseFloat(element.getAttribute("data-stagger")) || 0.1;
    if (mode === "block") {
      gsap.set(element, { y: 40, opacity: 0, visibility: "visible" });
      gsap.to(element, {
        y: 0,
        opacity: 1,
        duration: d_duration,
        delay: d_delay,
        ease: "power2.out",
        scrollTrigger: {
          trigger: element,
          start: "top 85%",
          toggleActions: "play none none none",
        },
      });
    }
    else if (mode === "text") {
      if ("ontouchstart" in window || navigator.maxTouchPoints > 0) {
        gsap.set(element, { opacity: 0, visibility: "visible" });
        gsap.to(element, {
          opacity: 1,
          duration: d_duration,
          scrollTrigger: { trigger: element, start: "top 85%" },
        });
        return;
      }
      document.fonts.ready.then(() => {
        const split = new SplitText(element, {
          type: "lines",
          linesClass: "split-line",
        });
        gsap.set(element, { autoAlpha: 1 });
        gsap.set(split.lines, { yPercent: 100, opacity: 0 });
        gsap.to(split.lines, {
          yPercent: 0,
          opacity: 1,
          stagger: d_stagger,
          duration: d_duration,
          delay: d_delay,
          ease: "power2.out",
          scrollTrigger: { trigger: element, start: "top 85%" },
        });
      });
    }
    else if (mode === "scramble") {
      gsap.set(element, { opacity: 0, visibility: "visible" });
      gsap.to(element, {
        opacity: 1,
        duration: d_duration,
        delay: d_delay,
        ease: "power2.out",
        scrambleText: {
          text: element.innerText,
          chars: "upperCase",
          revealDelay: 0.1,
          speed: 0.3,
        },
        scrollTrigger: { trigger: element, start: "top 85%" },
      });
    }
  });
});

(function () {
  var canvas = document.getElementById('wf-globe');
  var wrap   = document.getElementById('wf-globe-wrap');
  if (!canvas || !wrap) return;              /* <-- added: skip on pages without the globe */
  var ctx    = canvas.getContext('2d');
  var DPR    = window.devicePixelRatio || 1;

  var SIZE, R, cx, cy;

  function resize() {
    var w = wrap.clientWidth  || 600;
    var h = wrap.clientHeight || 600;
    SIZE = Math.min(w, h);
    canvas.style.width  = SIZE + 'px';
    canvas.style.height = SIZE + 'px';
    canvas.width  = SIZE * DPR;
    canvas.height = SIZE * DPR;
    ctx.setTransform(1, 0, 0, 1, 0, 0);
    ctx.scale(DPR, DPR);
    cx = SIZE / 2;
    cy = SIZE / 2;
    R  = SIZE * 0.41;
  }

  resize();
  window.addEventListener('resize', resize);

  var LAT_STEP = 15;
  var LON_STEP = 15;
  var STEPS    = 180;
  var SPEED    = 0.005;

  function toXYZ(lat, lon) {
    return [
      Math.cos(lat) * Math.sin(lon),
      Math.sin(lat),
      Math.cos(lat) * Math.cos(lon),
    ];
  }
  function rotY(p, a) {
    return [
       p[0] * Math.cos(a) + p[2] * Math.sin(a),
       p[1],
      -p[0] * Math.sin(a) + p[2] * Math.cos(a),
    ];
  }
  function project(p) {
    return { sx: cx + p[0] * R, sy: cy - p[1] * R, z: p[2] };
  }

  var angle = 0;

  function strokeArc(pts, fColor, fWidth, bColor, bWidth) {
    for (var pass = 0; pass < 2; pass++) {
      var front   = pass === 1;
      var penDown = false;
      var lx = 0, ly = 0;
      ctx.beginPath();
      for (var i = 0; i < pts.length; i++) {
        var p = pts[i];
        if ((p.z >= 0) !== front) { penDown = false; continue; }
        var gap = !penDown || (p.sx - lx) * (p.sx - lx) + (p.sy - ly) * (p.sy - ly) > R * R * 0.72;
        gap ? ctx.moveTo(p.sx, p.sy) : ctx.lineTo(p.sx, p.sy);
        penDown = true; lx = p.sx; ly = p.sy;
      }
      ctx.strokeStyle = front ? fColor : bColor;
      ctx.lineWidth   = front ? fWidth : bWidth;
      ctx.stroke();
    }
  }

  function parallelPts(latDeg) {
    var lat = latDeg * Math.PI / 180;
    var pts = [];
    for (var i = 0; i <= STEPS; i++) {
      pts.push(project(rotY(toXYZ(lat, (i / STEPS) * Math.PI * 2), angle)));
    }
    return pts;
  }

  function meridianPts(lonDeg) {
    var lon = lonDeg * Math.PI / 180;
    var pts = [];
    for (var i = 0; i <= STEPS; i++) {
      pts.push(project(rotY(toXYZ((i / STEPS) * Math.PI - Math.PI / 2, lon), angle)));
    }
    return pts;
  }

  function draw() {
    ctx.clearRect(0, 0, SIZE, SIZE);

    ctx.save();
    ctx.beginPath();
    ctx.arc(cx, cy, R, 0, Math.PI * 2);
    ctx.clip();

    for (var lat = -90 + LAT_STEP; lat < 90; lat += LAT_STEP) {
      strokeArc(parallelPts(lat),
        'rgba(255,255,255,0.90)', 0.5,
        'rgba(255,255,255,0.18)', 0.5);
    }
    for (var lon = 0; lon < 360; lon += LON_STEP) {
      strokeArc(meridianPts(lon),
        'rgba(255,255,255,0.90)', 0.5,
        'rgba(255,255,255,0.18)', 0.5);
    }

    ctx.restore();

    ctx.beginPath();
    ctx.arc(cx, cy, R, 0, Math.PI * 2);
    ctx.strokeStyle = 'rgba(255,255,255,0.90)';
    ctx.lineWidth   = 0.5;
    ctx.stroke();

    angle += SPEED;
    requestAnimationFrame(draw);
  }

  draw();
}());

document.addEventListener("DOMContentLoaded", function () {

  let mm = gsap.matchMedia();

  mm.add("(max-width: 991px)", () => {

    const navButton = document.querySelector('.w-nav-button');
    const links = document.querySelectorAll('.nav_menu_link');
    const body = document.body;

    let openTimeout;

    gsap.set(links, {
      opacity: 0,
      y: 50,
      scale: 0.95,
      filter: "blur(10px)"
    });

    function openMenu() {
      body.classList.add('no-scroll');
      gsap.killTweensOf(links);

      openTimeout = setTimeout(() => {
        gsap.to(links, {
          opacity: 1,
          y: 0,
          scale: 1,
          filter: "blur(0px)",
          duration: 0.8,
          ease: "expo.out",
          stagger: {
            each: 0.08,
            from: "start"
          }
        });
      }, 200);
    }

    function closeMenu() {
      clearTimeout(openTimeout);
      body.classList.remove('no-scroll');
      gsap.killTweensOf(links);

      gsap.to(links, {
        opacity: 0,
        y: 50,
        scale: 0.95,
        filter: "blur(0px)",
        duration: 0.35,
        ease: "power2.inOut",
        stagger: {
          each: 0.04,
          from: "end"
        }
      });
    }

    function toggleMenu() {
      setTimeout(() => {
        if (navButton.classList.contains('w--open')) {
          openMenu();
        } else {
          closeMenu();
        }
      }, 30);
    }

    function handleLinkClick() {
      setTimeout(() => {
        closeMenu();
      }, 50);
    }

    if (navButton) {
      navButton.addEventListener('click', toggleMenu);
    }

    links.forEach(link => {
      link.addEventListener('click', handleLinkClick);
    });

    return () => {
      if (navButton) {
        navButton.removeEventListener('click', toggleMenu);
      }
      links.forEach(link => {
        link.removeEventListener('click', handleLinkClick);
      });
      clearTimeout(openTimeout);
      body.classList.remove('no-scroll');
    };

  });

});

(function () {
  var CFG = {
    version:       1,
    maxAgeDays:    180,
    delayMs:       1400,
    optimizeId:    '117911758',
    clarityId:     '',
    privacyUrl:    '/privacy-policy',
    reloadOnGrant: false
  };
  var NAME = 'nc_consent';
  if (window.NCConsent) return;

  function read() {
    try {
      var m = document.cookie.match(/(?:^|;\s*)nc_consent=([^;]*)/);
      if (!m) return null;
      var v = JSON.parse(decodeURIComponent(m[1]));
      return v && v.v === CFG.version ? v : null;
    } catch (e) { return null; }
  }
  function write(state) {
    var payload = { v: CFG.version, ts: Date.now(), analytics: !!state.analytics, personalization: !!state.personalization };
    var exp = new Date(Date.now() + CFG.maxAgeDays * 864e5).toUTCString();
    document.cookie = NAME + '=' + encodeURIComponent(JSON.stringify(payload)) +
      ';expires=' + exp + ';path=/;SameSite=Lax' + (location.protocol === 'https:' ? ';Secure' : '');
    try { localStorage.setItem(NAME, JSON.stringify(payload)); } catch (e) {}
    return payload;
  }

  function withWf(cb, tries) {
    tries = tries || 0;
    if (window.wf && typeof window.wf.ready === 'function') {
      try { window.wf.ready(function () { cb(window.wf); }); } catch (e) {}
      return;
    }
    if (tries > 60) return;                    /* ~9s, then give up quietly */
    setTimeout(function () { withWf(cb, tries + 1); }, 150);
  }

  function apply(state) {
    if (typeof window.gtag === 'function') {
      window.gtag('consent', 'update', {
        analytics_storage: state.analytics ? 'granted' : 'denied',
        personalization_storage: state.personalization ? 'granted' : 'denied'
      });
    }

    if (typeof window.clarity === 'function') window.clarity('consent', !!state.analytics);
    if (CFG.clarityId && state.analytics && !document.querySelector('script[data-nc-clarity]')) {
      var s = document.createElement('script');
      s.async = true;
      s.setAttribute('data-nc-clarity', '');
      s.src = 'https://www.clarity.ms/tag/' + CFG.clarityId;
      document.head.appendChild(s);
    }

    /* Webflow Analyze + Optimize share one tracking switch.
       Official API: wf.allowUserTracking() / wf.denyUserTracking().
       The wf object is created by Webflow's async tracking script, so wait for it. */
    withWf(function (wf) {
      if (state.personalization) wf.allowUserTracking();
      else wf.denyUserTracking();
    });

    /* Belt and braces: takes effect before wf exists, and covers the case where
       Insights > Settings > Tracking is still on "Always track visitors". */
    try {
      var out = 'intellimize_opt_out_' + CFG.optimizeId;
      var choice = 'intellimize_user_tracking_choice_' + CFG.optimizeId;
      if (state.personalization) { localStorage.removeItem(out); localStorage.setItem(choice, 'allow'); }
      else {
        localStorage.setItem(out, 'true');
        localStorage.setItem(choice, 'deny');
        localStorage.setItem('intellimize_data_tracking_type', 'optOut');
      }
    } catch (e) {}

    document.dispatchEvent(new CustomEvent('nc:consent', { detail: state }));
  }

  var root = document.createElement('div');
  root.id = 'nc-cc';
  root.setAttribute('role', 'dialog');
  root.setAttribute('aria-label', 'Cookie preferences');
  root.hidden = true;
  root.innerHTML =
    '<div class="nc-drop"><div class="nc-chassis"><div class="nc-panel">' +
      '<div class="nc-rail">' +
        '<span class="nc-tick"></span>' +
        '<span class="nc-rail-label" data-rail>Cookies</span>' +
        '<span class="nc-rail-spacer"></span>' +
        '<button type="button" class="nc-back" data-act="back" hidden>&#8592; Back</button>' +
      '</div>' +
      '<div class="nc-body">' +
        '<div class="nc-view" data-view="notice">' +
          '<h2 class="nc-title">Choose what we measure</h2>' +
          '<p class="nc-copy">Some cookies keep the site running. The rest tell us which parts people actually read, so we can make it better. Full detail in the <a href="' + CFG.privacyUrl + '">privacy policy</a>.</p>' +
          '<div class="nc-actions">' +
            '<button type="button" class="nc-btn nc-btn--primary" data-act="all"><span>Accept all</span></button>' +
            '<button type="button" class="nc-btn" data-act="none"><span>Reject all</span></button>' +
          '</div>' +
          '<button type="button" class="nc-link" data-act="open">Customize <i>&#8250;</i></button>' +
        '</div>' +
        '<div class="nc-view" data-view="prefs" hidden>' +
          '<div class="nc-list">' +
            '<div class="nc-row">' +
              '<span class="nc-idx">01</span>' +
              '<div><span class="nc-name">Necessary</span>' +
                '<p class="nc-desc">Page delivery, bot protection, and remembering this choice.</p>' +
                '<p class="nc-vendors">Cloudflare</p></div>' +
              '<span class="nc-always">Always on</span>' +
            '</div>' +
            '<div class="nc-row">' +
              '<span class="nc-idx">02</span>' +
              '<div><span class="nc-name">Analytics</span>' +
                '<p class="nc-desc">How many people visit, which sections hold attention, and where the page trips people up.</p>' +
                '<p class="nc-vendors">Google Analytics 4 &middot; Microsoft Clarity</p></div>' +
              '<button type="button" class="nc-switch" role="switch" aria-checked="false" data-key="analytics" aria-label="Analytics cookies"></button>' +
            '</div>' +
            '<div class="nc-row">' +
              '<span class="nc-idx">03</span>' +
              '<div><span class="nc-name">Personalization</span>' +
                '<p class="nc-desc">Tests different versions of a page, remembers which one you were shown, and records how the site is used. These share one switch.</p>' +
                '<p class="nc-vendors">Webflow Optimize &middot; Webflow Analyze</p></div>' +
              '<button type="button" class="nc-switch" role="switch" aria-checked="false" data-key="personalization" aria-label="Personalization cookies"></button>' +
            '</div>' +
          '</div>' +
          '<div class="nc-actions">' +
            '<button type="button" class="nc-btn nc-btn--primary" data-act="save"><span>Save preferences</span></button>' +
          '</div>' +
        '</div>' +
      '</div>' +
    '</div></div></div>';

  var draft = { analytics: false, personalization: false };
  var rail = root.querySelector('[data-rail]');
  var back = root.querySelector('[data-act="back"]');

  function view(name) {
    root.querySelectorAll('.nc-view').forEach(function (v) { v.hidden = v.dataset.view !== name; });
    var prefs = name === 'prefs';
    rail.textContent = prefs ? 'Preferences' : 'Cookies';
    back.hidden = !prefs;
  }
  function paint() {
    root.querySelectorAll('.nc-switch').forEach(function (s) {
      s.setAttribute('aria-checked', draft[s.dataset.key] ? 'true' : 'false');
    });
  }
  function show(startOnPrefs) {
    var saved = read();
    draft = { analytics: !!(saved && saved.analytics), personalization: !!(saved && saved.personalization) };
    paint();
    view(startOnPrefs ? 'prefs' : 'notice');
    root.hidden = false;
    root.classList.add('nc-enter');
    requestAnimationFrame(function () {
      requestAnimationFrame(function () { root.classList.remove('nc-enter'); });
    });
    if (startOnPrefs) back.focus();
  }
  function hide() {
    root.classList.add('nc-enter');
    setTimeout(function () { root.hidden = true; }, 320);
  }
  function commit(state) {
    var prev = read();
    var wasDenied = !(prev && prev.personalization);
    apply(write(state));
    hide();
    if (CFG.reloadOnGrant && state.personalization && wasDenied) setTimeout(function () { location.reload(); }, 360);
  }

  root.addEventListener('click', function (e) {
    var sw = e.target.closest('.nc-switch');
    if (sw) { draft[sw.dataset.key] = !draft[sw.dataset.key]; paint(); return; }
    var btn = e.target.closest('[data-act]');
    if (!btn) return;
    var act = btn.dataset.act;
    if (act === 'all')  return commit({ analytics: true,  personalization: true });
    if (act === 'none') return commit({ analytics: false, personalization: false });
    if (act === 'save') return commit({ analytics: draft.analytics, personalization: draft.personalization });
    if (act === 'open') { view('prefs'); back.focus(); }
    if (act === 'back') { view('notice'); root.querySelector('[data-act="open"]').focus(); }
  });

  root.addEventListener('keydown', function (e) {
    if (e.key !== 'Escape') return;
    if (!root.querySelector('[data-view="prefs"]').hidden) { view('notice'); root.querySelector('[data-act="open"]').focus(); }
  });

  function boot() {
    document.body.appendChild(root);

    document.addEventListener('click', function (e) {
      var t = e.target.closest('a[href="#cookie-settings"], [data-nc-cookie-settings]');
      if (!t) return;
      e.preventDefault();
      show(true);
    });

    var saved = read();
    if (saved) { apply(saved); return; }
    setTimeout(function () { show(false); }, CFG.delayMs);
  }

  window.NCConsent = {
    open:  function () { show(true); },
    get:   read,
    reset: function () {
      document.cookie = NAME + '=;expires=Thu, 01 Jan 1970 00:00:00 GMT;path=/';
      try { localStorage.removeItem(NAME); } catch (e) {}
      show(false);
    }
  };

  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot);
  else boot();
})();

